"""Generated by the tkinter-ui skill (Windows 11 look)."""
import os
import sys
from pathlib import Path

candidates = [os.environ.get("TKUI_TKWIN11_PATH"),
              Path(__file__).resolve().parent / "tkwin11-main",
              Path.cwd() / "tkwin11-main"]
for candidate in candidates:
    if not candidate:
        continue
    candidate = Path(candidate)
    if (candidate / "tkwin11" / "__init__.py").is_file():
        sys.path.insert(0, str(candidate))
        break

import tkinter as tk
from tkinter import ttk
import tkwin11 as UI


def main():
    UI.enable_dpi_awareness()
    root = tk.Tk()
    root.title('TkUI Form')
    root.geometry("1000x700")
    UI.apply_theme(root)
    UI.configure_fluent(root)

    page = UI.FluentPage(root)
    page.pack(fill="both", expand=True)
    frame = ttk.Frame(page.body)
    frame.pack(fill="both", expand=True)
    ttk.Label(frame, text="New task",
              font=("Microsoft YaHei UI", 16, "bold")).pack(anchor="w")
    ttk.Label(frame, text="Fill the fields below.",
              style="Muted.TLabel").pack(anchor="w", pady=(4, 16))
    section = UI.SectionCard(frame, text="Details")
    section.pack(fill="x")
    ttk.Label(section, text="Task name").pack(anchor="w")
    ttk.Entry(section).pack(fill="x", pady=6)
    UI.ThemedCombobox(section, values=["Low", "Mid", "High"],
                      state="readonly").pack(fill="x", pady=6)
    UI.DateEntry(section, value="2026-10-30").pack(fill="x", pady=6)
    UI.RoundedText(section, height=5).pack(fill="x", pady=6)
    row = ttk.Frame(section)
    row.pack(anchor="w", pady=(12, 0))
    ttk.Button(row, text="Create", style="Primary.TButton",
               command=lambda: UI.notify(root, "Created", kind="success")).pack(side="left")
    ttk.Button(row, text="Cancel", style="Quiet.TButton").pack(side="left", padx=8)

    root.mainloop()


if __name__ == "__main__":
    main()
